@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    try {
        // Separate vertices into two partitions based on the first character of the key
        List<V> leftVertices  = new ArrayList<>();
        List<V> rightVertices = new ArrayList<>();
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            V value = entry.getValue();
            if (value == null) continue;
            // Add vertex to graph if not already present
            if (!target.containsVertex(value)) {
                target.addVertex(value);
            }
            // Simple partitioning rule: keys starting with a letter from A-M go left, N-Z go right
            if (!key.isEmpty() && Character.toUpperCase(key.charAt(0)) <= 'M') {
                leftVertices.add(value);
            } else {
                rightVertices.add(value);
            }
        }
        // Connect every vertex in the left partition to every vertex in the right partition
        for (V u : leftVertices) {
            for (V v : rightVertices) {
                if (!target.containsEdge(u, v)) {
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate bipartite graph", e);
    }
}

