    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    double sum = 0.0;
    for (V vertex : v) {
        if (vertex == null) {
            continue;
        }
        try {
            // Attempt to invoke a getWeight() method if present
            double weight = (double) vertex.getClass()
                                            .getMethod("getWeight")
                                            .invoke(vertex);
            sum += weight;
        } catch (Exception ignored) {
            // If getWeight() is not present or returns a non-double type,
            // ignore this vertex for the sum.
        }
    }
    return sum;
}

