private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null || start == null) {
        return null;
    }
    OuterFaceCirculator circ = start.getOuterFaceCirculator(dir);
    OuterFaceCirculator first = circ; // keep a reference to detect full loop
    while (true) {
        Node currentNode = circ.node();
        if (predicate.test(currentNode)) {
            return circ;
        }
        if (stop != null && currentNode.equals(stop)) {
            return circ;
        }
        circ = circ.next();
        // if we wrapped around to the starting position without success, break to avoid infinite loop
        if (circ == first) {
            return null;
        }
    }
}

