private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    try {
        if (bounds == null || bounds.isEmpty()) {
            return new Pair<>(new ArrayList<>(), 0L);
        }
        long total = 0L;
        for (Integer val : bounds) {
            if (val == null) {
                throw new IllegalArgumentException("Bounds list contains null element");
            }
            total += val;
        }
        List<Integer> suffix = new ArrayList<>(bounds.size());
        long suffixSum = 0L;
        for (int i = bounds.size() - 1; i >= 0; i--) {
            suffixSum += bounds.get(i);
            suffix.add(0, (int) suffixSum); // insert at front to maintain order
        }
        return new Pair<>(suffix, total);
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute suffix sum", e);
    }
}

