private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) return lowerBounds;
    for (int i = 0; i < keys.size(); i++){
        K key = keys.get(i);
        if (key == null){
            lowerBounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (int j = 0; j < keys.size(); j++){
            if (i == j) continue;
            K other = keys.get(j);
            if (other == null) continue;
            try{
                Integer val = (Integer)other;
                Integer cur = (Integer)key;
                if (val < cur && (maxLower == null || val > maxLower)){
                    maxLower = val;
                }
            }catch(ClassCastException e){
                // skip non-Integer keys
                continue;
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

