public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        // Resolve the relativePath against the base path using java.nio.file
        java.nio.file.Path basePath = java.nio.file.Paths.get(path).toAbsolutePath();
        java.nio.file.Path resultPath = basePath.resolve(relativePath).normalize();
        return resultPath.toString();
    } catch (Exception e) {
        // If the resolution fails, fallback to simple string manipulation
        String sep = java.io.File.separator;
        if (!path.endsWith(sep)) {
            path = path + sep;
        }
        String combined = path + relativePath;
        // Normalize .. segments manually
        String[] parts = combined.split(sep);
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }
        return String.join(sep, stack);
    }
}

