        while (start != -1) {
            int end = result.indexOf("}", start + 2);
            if (end == -1) {
                break; // unmatched ${, stop processing
            }
            String placeholder = result.substring(start + 2, end);
            String replacement = props.getProperty(placeholder, "");
            result = result.substring(0, start) + replacement + result.substring(end + 1);
            start = result.indexOf("${");
        }
    } catch (Exception e) {
        // In case of any unexpected issue, return the original or an empty string
        return "";
    }
    return result;
}

