protected int removeUnusedNodes(){
    if (root == null){
        return 0;
    }
    int removed = 0;
    java.util.Deque<Category> stack = new java.util.LinkedList<>();
    stack.push(root);
    while (!stack.isEmpty()){
        Category node = stack.pop();
        if (node == null){
            continue;
        }
        // Push children onto stack for later processing
        for (Category child : node.getChildren()){
            if (child != null){
                stack.push(child);
            }
        }
        // Remove inactive node from its parent
        if (!node.isActive()){
            Category parent = node.getParent();
            if (parent != null){
                parent.removeChild(node);
                removed++;
            }
        }
    }
    return removed;
}

