    }
    int count = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        int cp = str.codePointAt(i);
        int charCount = Character.charCount(cp);
        if (i + charCount > end) {
            throw new IndexOutOfBoundsException("Incomplete surrogate pair");
        }
        if (cp <= 0x7F) {
            count += 1;
        } else if (cp <= 0x7FF) {
            count += 2;
        } else if (cp <= 0xFFFF) {
            count += 3;
        } else {
            count += 4;
        }
        i += charCount;
    }
    return count;
}

