    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string of length " + length);
        }
        offset += read;
    }
